insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e4772073-ca44-46e2-b0b2-ba7d8a0c5480', '85a95099-b14b-4f8a-9ae5-7d56a9a930b3', $$uit een krant: de prijs van Hollandse garnalen op de visveiling stijgt van € 3,50 naar € 8 per kilo (met foto garnalenkotter)$$,
   $$economie-havo-2021-i-zo-goud-als-een-garnaal-context1.png$$,
   $$uit een krant: Een garnalenkotter uit Arnemuiden vangt dagelijks duizenden kilo’s Hollandse garnalen. Op dit moment zijn ze “goud” waard. De prijzen rijzen de pan uit. “Ik heb dit nog nooit meegemaakt”, zegt schipper Rinus. “Verse garnalen zijn kort houdbaar. We brengen onze vangst altijd meteen naar de visveiling en hopen op een goede prijs. We hadden verwacht ongeveer € 3,50 per kilo te krijgen, nu stopt de veilingklok op € 8.” Rinus vermoedt dat de prijsstijging te maken heeft met de verminderde garnalenstand in de Noordzee als gevolg van ongunstige weersomstandigheden.$$, 'inline'),
  ('ab319b57-eeaa-4fd8-8ba9-a0bc5308aadb', '85a95099-b14b-4f8a-9ae5-7d56a9a930b3', $$schipper John overweegt een technische aanpassing om de vangstcapaciteit te vergroten (zie bron 2)$$,
   $$economie-havo-2021-i-zo-goud-als-een-garnaal-context2.png$$,
   $$Schipper John wil maximaal profiteren van de hoge garnalenprijs. Hij overweegt om te investeren in een technische aanpassing van zijn garnalenkotter, zodat de vangstcapaciteit toeneemt. Met een grotere vangstcapaciteit denkt hij zijn maximale winst te kunnen verhogen.$$, 'inline'),
  ('27823384-e515-4dd0-8233-cbcdfd5b16c8', '85a95099-b14b-4f8a-9ae5-7d56a9a930b3', $$twee uitspraken van Rinus over de investering van John$$,
   $$economie-havo-2021-i-zo-goud-als-een-garnaal-context3.png$$,
   $$Rinus vindt de voorgenomen investering van John niet verstandig en doet de volgende uitspraken:
1 “De hoge prijs van Hollandse garnalen is waarschijnlijk van korte duur. Veranderingen in vraag en aanbod kunnen via het marktmechanisme zowel tot hogere als tot lagere prijzen leiden.”
2 “Als John zijn investering realiseert, mag de prijs van de Hollandse garnaal niet onder de € ... per kilo komen, anders wordt zijn maximale totale winst in de nieuwe situatie lager dan in de oude situatie.”$$, 'inline'),
  ('54539f91-2aa9-40f8-acd2-9f6f0e9d5a78', '85a95099-b14b-4f8a-9ae5-7d56a9a930b3', $$bron 1: vier grafieken met veranderingen in vraag en aanbod van Hollandse garnalen$$,
   $$economie-havo-2021-i-zo-goud-als-een-garnaal-context4.png$$,
   $$bron 1 veranderingen vraag en aanbod Hollandse garnalen op de visveiling als gevolg van ongunstige weersomstandigheden
vier grafieken met P (in €) tegen Q (in kilogram), prijzen 3,50 en 8 aangegeven:
grafiek 1: verticale aanbodlijn verschuift van Qa naar Qa'' (naar links), vraaglijn Qv blijft gelijk
grafiek 2: verticale aanbodlijn Qa blijft gelijk, vraaglijn verschuift van Qv naar Qv'' (naar rechts)
grafiek 3: stijgende aanbodlijn verschuift van Qa naar Qa'' (naar links), vraaglijn Qv blijft gelijk
grafiek 4: stijgende aanbodlijn Qa blijft gelijk, vraaglijn verschuift van Qv naar Qv'' (naar rechts)$$, 'inline'),
  ('6e0548de-6650-424b-8021-0266172de5fc', '85a95099-b14b-4f8a-9ae5-7d56a9a930b3', $$bron 2: gegevens garnalenkotter van schipper John vóór en na de aanpassing$$,
   $$economie-havo-2021-i-zo-goud-als-een-garnaal-context5.png$$,
   $$bron 2 gegevens garnalenkotter van schipper John
vóór voorgenomen effect van de aanpassing voorgenomen aanpassing
vangstcapaciteit kotter 125.000 kilogram + 50.000 kilogram
gemiddelde variabele € 2,20 + 25% kosten per kilogram
totale constante € 480.000 + € 50.000 kosten$$, 'inline'),
  ('fca4ab26-7b4d-4f05-87c9-3df2250233fd', 'de4df434-8b45-4561-bce7-e1664af152e5', $$India: het nominale bbp per hoofd van de bevolking is in 2012-2017 bijna verdubbeld$$,
   $$economie-havo-2021-i-meer-vrijhandel-meer-groei-context1.png$$,
   $$In de periode 2012–2017 was India een van de snelst groeiende economieën van de wereld. Het nominale bruto binnenlands product (bbp) per hoofd van de bevolking is in die periode bijna verdubbeld. De groei van het nominale bbp is voornamelijk te verklaren door een toename van de consumptie van de middenklasse en door een toename van de buitenlandse investeringen.$$, 'inline'),
  ('8ce00f75-e146-4c49-a833-68bb35a5b576', 'de4df434-8b45-4561-bce7-e1664af152e5', $$twee uitspraken van een Indiase econoom over welvaart en infrastructuur$$,
   $$economie-havo-2021-i-meer-vrijhandel-meer-groei-context2.png$$,
   $$Een Indiase econoom stelt:
1 “Hoewel het nominale bbp per hoofd van de bevolking bijna is verdubbeld, betekent dat niet dat de welvaart in India ook bijna twee keer zo groot is.”
2 “Het belangrijkste probleem in India is de matige infrastructuur. Daarom moet de overheid daar fors in investeren.”$$, 'inline'),
  ('30f18e26-867a-4d94-9ec5-dbbc13091a62', 'de4df434-8b45-4561-bce7-e1664af152e5', $$EU en India onderhandelen over het afschaffen van 120% invoerrechten op Europese auto's$$,
   $$economie-havo-2021-i-meer-vrijhandel-meer-groei-context3.png$$,
   $$Door de hoge economische groei is India voor de Europese Unie (EU) een potentieel grote afzetmarkt. Maar als gevolg van protectionistische maatregelen blijft de handel tussen India en de EU beperkt. Zo hebben Europese exporteurs van auto’s te maken met 120% invoerrechten in India. De EU is nu met India in onderhandeling over het afschaffen van invoerrechten op Europese producten in ruil voor minder strenge Europese regelgeving voor producten uit India.$$, 'inline'),
  ('8aee5d50-7cf4-41c1-89a6-3a4f5ed7fef2', 'de4df434-8b45-4561-bce7-e1664af152e5', $$de econoom: India en de EU kunnen profiteren van meer vrijhandel, geen gevangenendilemma (zie bron 2)$$,
   $$economie-havo-2021-i-meer-vrijhandel-meer-groei-context4.png$$,
   $$De econoom is positief over de onderhandelingen en stelt: “Zowel India als de EU kan profiteren van meer vrijhandel. Ik heb de effecten hiervan onderzocht en in een pay-off-matrix gezet (zie bron 2). Hieruit blijkt dat er geen gevangenendilemma zal zijn.”$$, 'inline'),
  ('82a7cb32-ae96-4b52-afab-8ea2446d842a', 'de4df434-8b45-4561-bce7-e1664af152e5', $$bron 1: kerngegevens Indiase economie en bevolking 2012-2017$$,
   $$economie-havo-2021-i-meer-vrijhandel-meer-groei-context5.png$$,
   $$bron 1 kerngegevens Indiase economie en bevolking
2012 2013 2014 2015 2016 2017
indexcijfer reëel bbp 100 112 119,8 128,5 137,9 148,2
consumentenprijsindexcijfer 100 109,9 120,2 127,3 133,7 140,8 (CPI)
bevolkingsomvang 1.264 1.279 1.295 1.311 1.327 1.342 (in miljoenen personen)$$, 'inline'),
  ('9d3925f1-5468-4ebc-ba0e-5d1613c45525', 'de4df434-8b45-4561-bce7-e1664af152e5', $$bron 2: pay-off-matrix voor extra economische groei India en EU$$,
   $$economie-havo-2021-i-meer-vrijhandel-meer-groei-context6.png$$,
   $$bron 2 pay-off-matrix voor extra economische groei India en EU (India ; EU)
India \ EU | afschaffen strenge regelgeving voor importproducten | handhaven strenge regelgeving voor importproducten
afschaffen invoerrechten | 2% ; 1,5% | 1% ; 0,5%
handhaven invoerrechten | 0,5% ; 1% | 0% ; 0%$$, 'inline'),
  ('bd0a3178-c85a-4647-95fb-d08da0261969', '3a206523-2b8d-4bb6-be1d-9597a44d1c3d', $$fragment 1: door de crisis liep het overheidstekort op tot € 34 miljard in 2010$$,
   $$economie-havo-2021-i-overheidsfinancien-op-koers-context1.png$$,
   $$fragment 1 uit een economisch rapport: Door de economische crisis die in 2008 begon, liep het overheidstekort in Nederland op tot € 34 miljard in 2010. Bedrijfswinsten daalden en daarmee de belastinginkomsten. Tegelijk liepen de overheidsuitgaven sterk op: door toename van het aantal werklozen steeg het aantal uitkeringen. In 2010 heeft het overheidstekort van € 34 miljard geleid tot een toename van de overheidsschuld van minder dan € 34 miljard (zie bron 1).$$, 'inline'),
  ('a7b3faac-7988-45d6-9e73-04db69be4a98', '3a206523-2b8d-4bb6-be1d-9597a44d1c3d', $$fragment 2: maatregelen om aan de eisen van het Stabiliteitspact te voldoen; banenverlies$$,
   $$economie-havo-2021-i-overheidsfinancien-op-koers-context2.png$$,
   $$fragment 2 uit een economisch rapport: Om aan de eisen van het Stabiliteitspact (zie bron 2) van de Economische en Monetaire Unie (EMU) te voldoen, heeft de Nederlandse overheid in de periode 2010–2015 diverse maatregelen genomen. Zo werden de overheidsuitgaven verlaagd en de overheidsinkomsten verhoogd (zie bron 3), waardoor de begroting van 2015 redelijk op orde is gekomen (zie bron 1). Maar als gevolg van die maatregelen zijn er wel bijna 400.000 banen verloren gegaan.$$, 'inline'),
  ('f37b2287-bef6-4cbd-b755-fe03a577935b', '3a206523-2b8d-4bb6-be1d-9597a44d1c3d', $$bron 1: overheidssaldo, overheidsschuld en bbp in de periode 2008-2015$$,
   $$economie-havo-2021-i-overheidsfinancien-op-koers-context3.png$$,
