1p 2 Welke grafiek geeft het vermoeden van Rinus weer over de oorzaak van de prijsstijging?$$, array['e4772073-ca44-46e2-b0b2-ba7d8a0c5480', '54539f91-2aa9-40f8-acd2-9f6f0e9d5a78']::uuid[]),
